head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil30604";
scwin.row = 0;
scwin.seq = "";
scwin.eduStrtDdtm = "";
scwin.eduEndDdtm = "";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_ctxDefaults();
        await scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil30604.onpageload' });
    }
};

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "txa_reqContn", attr: "label", fn: function () { return String(dma_lecrDiptList.get("reqContn")); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_ctxDefaults
 * @description 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다. 진입 기본값 충전 — 파라미터로 안 온 키에 스펙 기본값(조건 평가보다 먼저).
 * @returns {void}
 * @hidden N
 */
scwin.init_ctxDefaults = function () {
    const cds = {"cnt":"0"};
    const pc0 = $c.util.getComponent("dma_pageContext");
    if (!pc0 || !pc0.get || !pc0.set) { return; }
    for (let ck in cds) { const cv0 = pc0.get(ck); if (cv0 === undefined || cv0 === null || cv0 === '') { pc0.set(ck, cds[ck]); } }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_chrgNm", fn: function(){ return (!(String(((dma_corpDisclsChrg1.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "corpDisclsChrg1.chrgNm"); })())) == null ? '' : ((dma_corpDisclsChrg1.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "corpDisclsChrg1.chrgNm"); })()))).length === 0)); } }, { id: "if_chrgNm_2", fn: function(){ return (!(String(((dma_corpDisclsChrg2.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "corpDisclsChrg2.chrgNm"); })())) == null ? '' : ((dma_corpDisclsChrg2.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "corpDisclsChrg2.chrgNm"); })()))).length === 0)); } }, { id: "if_chrgNm_3", fn: function(){ return (!(String(((dma_corpDisclsChrg3.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "corpDisclsChrg3.chrgNm"); })())) == null ? '' : ((dma_corpDisclsChrg3.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "corpDisclsChrg3.chrgNm"); })()))).length === 0)); } }, { id: "if_chrgNm_4", fn: function(){ return (!(String(((dma_corpDisclsChrg4.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "corpDisclsChrg4.chrgNm"); })())) == null ? '' : ((dma_corpDisclsChrg4.get("chrgNm") ?? (() => { throw new Error("unresolved:" + "corpDisclsChrg4.chrgNm"); })()))).length === 0)); } }, { id: "if_chrgNm_4", fn: function(){ return ((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })()) === '1'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["comAbbrv"] ?? ""); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_register();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name rd_inDataYn_onclick
 * @description rd_inDataYn 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.rd_inDataYn_onclick = function(e){
    try {
        scwin.inCharge('N')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil30604.rd_inDataYn_onclick' }); }
};

/**
 * @method
 * @name slc_name1_onchange
 * @description slc_name1 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_name1_onchange = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.selCharge(selfVar.value);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil30604.slc_name1_onchange' }); }
};

/**
 * @method
 * @name rowPlus_oncellclick
 * @description rowPlus 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.rowPlus_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_lecrDiptSchdl');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_lecrDiptSchdl */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.inRows(); return;
        await scwin.delRows(); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'rowPlus.oncellclick' });
    }
};

/**
 * @method
 * @name txa_reqContn_onkeyup
 * @description txa_reqContn 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txa_reqContn_onkeyup = async function(e){
    try {
        await scwin.checkByte($c.util.getComponent("txa_reqContn"))

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil30604.txa_reqContn_onkeyup' }); }
};

/**
 * @method
 * @name txa_reqContn_onfocus
 * @description txa_reqContn 포커스 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.txa_reqContn_onfocus = function(e){
    try {
        scwin.firstWrite();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil30604.txa_reqContn_onfocus' }); }
};

/**
 * @method
 * @name txa_reqContn_onchange
 * @description txa_reqContn 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txa_reqContn_onchange = async function(e){
    try {
        await scwin.checkByte($c.util.getComponent("txa_reqContn"))

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil30604.txa_reqContn_onchange' }); }
};

/**
 * @method
 * @name btn_register_onclick
 * @description 「임시저장」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_register_onclick = async function(e){
    try {
        await scwin.register('Y')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil30604.btn_register_onclick' }); }
};

/**
 * @method
 * @name btn_register_2_onclick
 * @description 「신청」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_register_2_onclick = async function(e){
    try {
        await scwin.register('')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil30604.btn_register_2_onclick' }); }
};

/**
 * @method
 * @name btn_goList_onclick
 * @description 「목록」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_goList_onclick = async function(e){
    try {
        await scwin.goList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil30604.btn_goList_onclick' }); }
};

/**
 * @method
 * @name rowPlus_oneditend
 * @description rowPlus oneditend 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {*} value value
 * @returns {void}
 * @hidden N
 */
scwin.rowPlus_oneditend = function (rowIndex, columnIndex, value) {  };

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_goList
 * @description go List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goList = async function () {
    const sbmOptions = {
        id: "tx_fn_goList",
        method: "post",
        action: "/issue/lecrDipt.do",
        ref: "dma_goListReq",
        target: "dlt_lecrDiptSchdl=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_register
 * @description register 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_register = async function () {
    const sbmOptions = {
        id: "tx_fn_register",
        method: "post",
        action: "/issue/lecrDipt.do",
        ref: "dma_registerReq",
        target: "dlt_lecrDiptSchdl=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name goList
 * @description go List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goList = async function () {
    const frm = (document.LecrDiptForm || { elements: [] });
    frm.action = 'lecrDipt.do';
    $c.util.getComponent('dma_goListReq').set('method', 'searchLecrDipt');
    const nr = await scwin.tx_fn_goList();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil30601/jldfil30601.xml", { "method": 'searchLecrDipt' });
    }
};

/**
 * @method
 * @name register
 * @description register 처리
 * @param {String} tempSaveYn tempSaveYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function (tempSaveYn) {
    let q_name = "";
    if (document.getElementsByName("rd_inDataYn")[0].checked === true) {
        q_name = document.getElementsByName("slc_name1");
        let q_cnt = 0;
        for (let n = 0; n < q_name.length; n++) {
            if (q_name[n].value === "0" || q_name[n].value === "1" || q_name[n].value === "2") {
                q_cnt++;
                q_name[n].checked === true;
            }
        }
        if (q_cnt === 0) {
            $c.util.getComponent('ipt_contactpnt').setValue("");
            $c.util.getComponent('ipt_email').setValue("");
            await $c.win.alert("'신청자명' 항목을 선택하세요.");
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return;
        }
    } else {
        if (document.getElementsByName("rd_inDataYn")[1].checked === true) {
            q_name = $c.util.getComponent("ipt_name2");
            if (await scwin.nullChk(q_name)) {
                return;
            }
        } else {
            await $c.win.alert("'신청자정보'를 선택하세요.");
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return;
        }
    }
    if (await scwin.nullChk($c.util.getComponent("ipt_contactpnt"))) {
        return;
    }
    if (/^[0-9-]*$/.test($c.util.getComponent('ipt_contactpnt').getValue()) === false) {
        await $c.win.alert("숫자와 '-'만 입력가능합니다.");
        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
        return;
    }
    if (await scwin.nullChk($c.util.getComponent("ipt_email"))) {
        return;
    }
    if ($c.str.isEmail($c.util.getComponent('ipt_email').getValue()) === false) {
        return;
    }
    if (await scwin.nullChk($c.util.getComponent("ipt_eduLocNm"))) {
        return;
    }
    for (n = 0; n < scwin.row; n++) {
        const objSDd = "eduStrtDd_" + n;
        const objSHh = "eduStrtHh_" + n;
        const objSMm = "eduStrtMm_" + n;
        const objEDd = "eduEndDd_" + n;
        const objEHh = "eduEndHh_" + n;
        const objEMm = "eduEndMm_" + n;
        if (await scwin.nullChk($c.util.getComponent(objSDd))) {
            return;
        }
        if (await scwin.nullChk($c.util.getComponent(objSHh))) {
            return;
        }
        if (await scwin.nullChk($c.util.getComponent(objSMm))) {
            return;
        }
        if (await scwin.nullChk($c.util.getComponent(objEDd))) {
            return;
        }
        if (await scwin.nullChk($c.util.getComponent(objEHh))) {
            return;
        }
        if (await scwin.nullChk($c.util.getComponent(objEMm))) {
            return;
        }
        if (parseInt($c.util.getComponent(objSDd).getValue()) > parseInt($c.util.getComponent(objEDd).getValue())) {
            await $c.win.alert("시작일보다 이전 일자를 입력하실 수 없습니다.");
            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
            return;
        } else {
            if (parseInt($c.util.getComponent(objSDd).getValue()) === parseInt($c.util.getComponent(objEDd).getValue())) {
                if (parseInt($c.util.getComponent(objSHh).getValue()) > parseInt($c.util.getComponent(objEHh).getValue())) {
                    await $c.win.alert("시작시간보다 이전 시간을 입력하실 수 없습니다.");
                    /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                    return;
                } else {
                    if (parseInt($c.util.getComponent(objSHh).getValue()) === parseInt($c.util.getComponent(objEHh).getValue())) {
                        if (parseInt($c.util.getComponent(objSMm).getValue()) > parseInt($c.util.getComponent(objEMm).getValue())) {
                            await $c.win.alert("시작시간보다 이전 시간을 입력하실 수 없습니다.");
                            /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                            return;
                        } else {
                            if (parseInt($c.util.getComponent(objSMm).getValue()) === parseInt($c.util.getComponent(objEMm).getValue())) {
                                await $c.win.alert("시작시간과 같은 시간을 입력하실 수 없습니다.");
                                /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
                                return;
                            }
                        }
                    }
                }
            }
        }
        scwin.dataSet(n, objSDd, objSHh, objSMm, objEDd, objEHh, objEMm);
    }
    $c.util.getComponent('ipt_seq').setValue(scwin.seq);
    $c.util.getComponent('ipt_eduStrtDdtm').setValue(scwin.eduStrtDdtm);
    $c.util.getComponent('ipt_eduEndDdtm').setValue(scwin.eduEndDdtm);
    if (await scwin.nullChk($c.util.getComponent("ipt_eduPrnNm"))) {
        return;
    }
    if (await scwin.nullChk($c.util.getComponent("ipt_eduPartcCnt"))) {
        return;
    }
    if (await scwin.nullChk($c.util.getComponent("txa_reqContn"))) {
        return;
    }
    const frm = (document.LecrDiptForm || { elements: [] });
    frm.action = 'lecrDipt.do';
    $c.util.getComponent('dma_goListReq').set('method', 'registLecrDipt');
    $c.util.getComponent('dma_goListReq').set('eduApplSeq', '' + dma_pageContext.get("eduApplSeq") + '');
    if (tempSaveYn === 'Y') {
        $c.util.getComponent('dma_goListReq').set('tempSaveYn', 'Y');
        $c.util.getComponent('dma_goListReq').set('lecrDiptProcsStatCd', '');
    } else {
        $c.util.getComponent('dma_goListReq').set('lecrDiptProcsStatCd', '00');
    }
    if (document.getElementsByName("rd_inDataYn")[1].checked === true) {
        $c.util.getComponent('dma_goListReq').set('apctNm', q_name.value);
    }
    await scwin.tx_fn_register();
};

/**
 * @method
 * @name dataSet
 * @description data Set 처리
 * @param {Number} n n
 * @param {String} objSDd objSDd
 * @param {*} objSHh objSHh
 * @param {*} objSMm objSMm
 * @param {String} objEDd objEDd
 * @param {*} objEHh objEHh
 * @param {*} objEMm objEMm
 * @returns {void}
 * @hidden N
 */
scwin.dataSet = function (n, objSDd, objSHh, objSMm, objEDd, objEHh, objEMm) {
    const eduSDd = $c.util.getComponent(objSDd).getValue().split("-").join("");
    const eduEDd = $c.util.getComponent(objEDd).getValue().split("-").join("");
    let eduSHh = "";
    let eduEHh = "";
    if ($c.util.getComponent(objSHh).getValue() < 10) {
        eduSHh = "0" + $c.util.getComponent(objSHh).getValue();
    } else {
        eduSHh = $c.util.getComponent(objSHh).getValue();
    }
    if ($c.util.getComponent(objEHh).getValue() < 10) {
        eduEHh = "0" + $c.util.getComponent(objEHh).getValue();
    } else {
        eduEHh = $c.util.getComponent(objEHh).getValue();
    }
    if (n === 0) {
        scwin.seq = (n + 1) + "";
        scwin.eduStrtDdtm = eduSDd + eduSHh + $c.util.getComponent(objSMm).getValue() + "00";
        scwin.eduEndDdtm = eduEDd + eduEHh + $c.util.getComponent(objEMm).getValue() + "00";
    } else {
        scwin.seq = scwin.seq + "," + (n + 1);
        scwin.eduStrtDdtm = scwin.eduStrtDdtm + "," + eduSDd + eduSHh + $c.util.getComponent(objSMm).getValue() + "00";
        scwin.eduEndDdtm = scwin.eduEndDdtm + "," + eduEDd + eduEHh + $c.util.getComponent(objEMm).getValue() + "00";
    }
};

/**
