                $c.util.getComponent('dma_lecrDiptList').set('apctNm', "" + dma_corpDisclsChrg3.get("chrgNm") + "");
                $c.util.getComponent('ipt_contactpnt').setValue("" + dma_corpDisclsChrg3.get("telNo") + "");
                $c.util.getComponent('ipt_email').setValue($c.util.getComponent('ipt_email').getValue());
            } else {
