/**
 * @method
 * @name delRows
 * @description del Rows 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delRows = async function () {
    const divID = "rowPlus";
    const rowPlus = $c.util.getComponent(divID);
    if (scwin.row > 1) {
        const no = rowPlus.rows.length - 1;
        dlt_lecrDiptSchdl.deleteRow(no);
        scwin.row--;
    } else {
        if (scwin.row < 2) {
            await $c.win.alert("최소한 1줄은 작성하셔야 합니다.");
        }
    }
};
